'use client';

import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Pagination from '@/components/products/Pagination';
import Navbar from '@/components/common/Navbar';

const ProductList = () => {
  const [products, setProducts] = useState([]);
  const [categories, setCategories] = useState([]);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('');
  const [minPrice, setMinPrice] = useState('');
  const [maxPrice, setMaxPrice] = useState('');

  useEffect(() => {
    fetchCategories();
    fetchProducts();
  }, [currentPage, searchQuery, selectedCategory, minPrice, maxPrice]);

  const fetchCategories = async () => {
    try {
      const response = await axios.get('http://localhost:8080/api/v1/categories');
      setCategories(response.data.data || []);
    } catch (error) {
      console.error('Error fetching categories:', error);
    }
  };

  const fetchProducts = async () => {
    try {
      const response = await axios.get('http://localhost:8080/api/v1/products', {
        params: {
          page: currentPage - 1,
          size: 10,
          name: searchQuery,
          category: selectedCategory,
          minPrice,
          maxPrice,
          sortField: 'createdAt',
          sortDirection: 'ASC',
        },
      });
      setProducts(response.data.content);
      setTotalPages(response.data.totalPages);
    } catch (error) {
      console.error('Error fetching products:', error);
    }
  };

  return (
    <div>
      <Navbar searchQuery={searchQuery} setSearchQuery={setSearchQuery} />
      <div className="container mx-auto p-4">
        <div className="flex space-x-4 mb-4">
          <input
            type="text"
            placeholder="Search products..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="border p-2"
          />
          <select
            value={selectedCategory}
            onChange={(e) => setSelectedCategory(e.target.value)}
            className="border p-2"
          >
            <option value="">All Categories</option>
            {categories.map((category) => (
              <option key={category} value={category}>{category}</option>
            ))}
          </select>
          <input
            type="number"
            placeholder="Min Price"
            value={minPrice}
            onChange={(e) => setMinPrice(e.target.value)}
            className="border p-2"
          />
          <input
            type="number"
            placeholder="Max Price"
            value={maxPrice}
            onChange={(e) => setMaxPrice(e.target.value)}
            className="border p-2"
          />
        </div>
        
        <div className="grid grid-cols-4 gap-4">
          {products.map((product) => (
            <div key={product.productId} className="border p-4">
              {product.productPictures ? (
                <img src={product.productPictures.productPictureUrl} alt={product.productName} className="w-full h-40 object-cover" />
              ) : (
                <div className="w-full h-40 bg-gray-200 flex items-center justify-center">No Image</div>
              )}
              <h2 className="font-bold mt-2">{product.productName}</h2>
              <p>{product.detail}</p>
              <p className="text-blue-500 font-bold">${product.price}</p>
              <p className="text-gray-500">Stock: {product.totalStock}</p>
            </div>
          ))}
        </div>

        <Pagination currentPage={currentPage} totalPages={totalPages} setCurrentPage={setCurrentPage} />
      </div>
    </div>
  );
};

export default ProductList;
